"""Writes the generated parts of docs/mapping.md from the mapping files.

Started as `python -m odrig.mapdoc [--check] [--page PATH] [--mapping-dir DIR]`.

A generated part of the page stands between a line that names it,

    <!-- generated by `python -m odrig.mapdoc`: <kind> <file> -->

and the next line `<!-- end of generated part -->`. The kind is `board`, `drawing` or
`table`. The file is a mapping file of the mapping folder, named without `.json`. What
stands between the two lines is replaced, and every other byte of the page stays.
"""

import argparse
import pathlib
import re
import sys

from . import errors, files, mapping

ROOT = pathlib.Path(__file__).resolve().parents[1]

# What this program says about a page. These are words of this module and not reasons of
# docs/reasons.md, which lists what the converter says about its inputs.
PAGE_DIFFERS = "page-differs"
PAGE_MALFORMED = "page-malformed"

_OPENING = b"<!-- generated by `python -m odrig.mapdoc`:"
_NAME = re.compile(rb" (board|drawing|table) ([A-Za-z0-9][A-Za-z0-9._-]*) -->")
_END = b"<!-- end of generated part -->"

# The labels of the board's two rows of pins, from the antenna end to the USB end. A label
# made of digits is the GPIO of that number.
BOARD_LEFT = ("3V3", "3V3", "RST", "4", "5", "6", "7", "15", "16", "17", "18", "8", "3", "46", "9", "10",
              "11", "12", "13", "14", "5Vin", "GND")
BOARD_RIGHT = ("GND", "TX", "RX", "1", "2", "42", "41", "40", "39", "38", "37", "36", "35", "0", "45", "48",
               "47", "21", "20", "19", "GND", "GND")

# What is written on the board, between its two rows of pins: above the first pins, and
# beside the pins counted from 0 at the antenna end.
_ABOVE_THE_PINS = "     antenna     "
_BESIDE_THE_PINS = {4: "    ESP32-S3     ", 5: "     N16R8       ", 21: "  [USB]   [USB]  "}
_INSIDE = len(_ABOVE_THE_PINS)

# The number of characters of the arrow of a strip.
_ARROW = 44


def board(canvas):
    """The drawing of the board seen from above, with each leg of the mapping beside the
    pin it is wired to. A leg whose pin is not on the board is named under the drawing."""
    legs = {str(leg.pin): leg.leg for leg in canvas.legs}
    name_width = max([6] + [len(f"leg {leg.leg}") for leg in canvas.legs])
    left_width = 3 + name_width + 3 + 4
    edge = " " * (left_width + 6) + "+" + "-" * _INSIDE + "+"
    lines = ["```", edge, " " * (left_width + 6) + "|" + _ABOVE_THE_PINS + "|"]
    for place, (left, right) in enumerate(zip(BOARD_LEFT, BOARD_RIGHT)):
        before = left.rjust(left_width)
        if left in legs:
            name = f"leg {legs[left]}"
            before = f"   {name:<{name_width}} --{left:>4}"
        after = right
        if right in legs:
            after = f"{right:<4}--  leg {legs[right]}"
        inside = _BESIDE_THE_PINS.get(place, " " * _INSIDE)
        lines.append(f"{before}  o---|{inside}|---o  {after}")
    lines += [edge, "```"]
    on_the_board = set(BOARD_LEFT) | set(BOARD_RIGHT)
    absent = [f"leg {leg.leg} on pin {leg.pin}" for leg in canvas.legs if str(leg.pin) not in on_the_board]
    if absent:
        lines += ["", f"Not on the board: {', '.join(absent)}."]
    return lines


def drawing(canvas):
    """The drawing of a mapping file, one line for each strip: the rows from the top one
    down, or the columns from x = 1 on. A line has the LED numbers at the two ends of its
    strip, an arrow that points the way the numbers grow, and the leg and the pin beside
    the first strip of a leg."""
    along, across = ("x", "y") if canvas.kind == mapping.ROWS else ("y", "x")
    length = canvas.strip_length
    strips = {}
    for leg in canvas.legs:
        for place, strip in enumerate(leg.strips):
            strips[strip] = (leg, place)
    order = sorted(strips, reverse=canvas.kind == mapping.ROWS)
    label_width = max(6, len(f"{across}={len(strips)}") + 2)
    number_width = len(str(max(canvas.led_count(leg) for leg in canvas.legs)))
    heading = " " * (label_width + 1) + f"{along}=1"
    heading += f"{along}={length}".rjust(label_width + 2 * number_width + _ARROW + 2 - len(heading))
    lines = ["```", heading]
    for strip in order:
        leg, place = strips[strip]
        first, last = place * length + 1, (place + 1) * length
        x, y = mapping.position(canvas, leg, first)
        starts_at_1 = (x if canvas.kind == mapping.ROWS else y) == 1
        at_1, at_the_far_end = (first, last) if starts_at_1 else (last, first)
        arrow = "-" * (_ARROW - 1) + ">" if starts_at_1 else "<" + "-" * (_ARROW - 1)
        label = f"{across}={strip}"
        line = f"{label:<{label_width}}| {at_1:>{number_width}} {arrow} {at_the_far_end:>{number_width}} |"
        if place == 0:
            line += f"  leg {leg.leg}, pin {leg.pin}"
        lines.append(line)
    lines.append("```")
    return lines


def table(canvas):
    """The table of a mapping file, one line for each leg: its number, its pin, its strips
    in chain order, and the canvas position of the first and of the last LED of every
    strip. It has as many pairs of columns as the longest leg has strips."""
    length = canvas.strip_length
    most = max(len(leg.strips) for leg in canvas.legs)
    heading = ["Leg", "Pin", "Rows (y)" if canvas.kind == mapping.ROWS else "Columns (x)"]
    for place in range(most):
        heading += [f"LED {place * length + 1}", f"LED {(place + 1) * length}"]
    lines = [_table_line(heading), "|---:|---:|" + "---|" * (1 + 2 * most)]
    for leg in canvas.legs:
        cells = [str(leg.leg), str(leg.pin), ", ".join(str(strip) for strip in leg.strips)]
        for place in range(most):
            for n in (place * length + 1, (place + 1) * length):
                cells.append("({},{})".format(*mapping.position(canvas, leg, n)) if place < len(leg.strips) else "")
        lines.append(_table_line(cells))
    return lines


def _table_line(cells):
    return "| " + " | ".join(cells) + " |"


_KINDS = {"board": board, "drawing": drawing, "table": table}


def _malformed(number, detail):
    return errors.Rejection(PAGE_MALFORMED, f"line {number + 1}: {detail}")


def _parts(lines):
    """The generated parts of a page given as its lines: for each one its name, the place
    of its marker and the place of its end."""
    parts = []
    marker = None
    for number, line in enumerate(lines):
        if line.startswith(_OPENING):
            if marker is not None:
                raise _malformed(marker, "the marker of a generated part has no end")
            marker = number
        elif line == _END:
            if marker is None:
                raise _malformed(number, "the end of a generated part has no marker")
            named = _NAME.fullmatch(lines[marker][len(_OPENING):])
            if named is None:
                written = lines[marker].decode("utf-8", "replace")
                raise _malformed(marker, f"{written} does not name a board, a drawing or a table of a mapping file")
            parts.append((named[1].decode("ascii"), named[2].decode("ascii"), marker, number))
            marker = None
    if marker is not None:
        raise _malformed(marker, "the marker of a generated part has no end")
    return parts


def write(page, folder, check=False):
    """Writes the generated parts of the page from the mapping files of the folder. With
    `check` nothing is written, and a page that would change is refused as `page-differs`
    with the name of its first generated part that differs."""
    data = files.read(page)
    lines = data.split(b"\n")
    with errors.naming(page):
        parts = _parts(lines)
    canvases = {}
    result = []
    differs = None
    copied = 0
    for kind, name, marker, end in parts:
        if name not in canvases:
            canvases[name] = mapping.read(pathlib.Path(folder, f"{name}.json"))
        made = [line.encode("ascii") for line in _KINDS[kind](canvases[name])]
        if differs is None and made != lines[marker + 1:end]:
            differs = f"{kind} {name}"
        result += lines[copied:marker + 1] + made
        copied = end
    result += lines[copied:]
    if differs is None:
        return
    if check:
        raise errors.Rejection(PAGE_DIFFERS, differs)
    files.write(page, b"\n".join(result))


def main(argv=None):
    """Runs one command line and returns the exit status."""

    def action():
        parser = argparse.ArgumentParser(
            prog="python -m odrig.mapdoc",
            description="Writes the drawings and tables of docs/mapping.md from the mapping files.",
        )
        parser.add_argument(
            "--check",
            action="store_true",
            help="write nothing, and fail when the page is not what would be written",
        )
        parser.add_argument(
            "--page",
            default=ROOT / "docs" / "mapping.md",
            metavar="PATH",
            help="the page to write (default: docs/mapping.md of the repository)",
        )
        parser.add_argument(
            "--mapping-dir",
            default=ROOT / "mapping",
            metavar="DIR",
            help="the folder of the mapping files (default: mapping/ of the repository)",
        )
        arguments = parser.parse_args(argv)
        write(arguments.page, arguments.mapping_dir, check=arguments.check)

    return errors.status_of(action)


if __name__ == "__main__":
    sys.exit(main())
